var DomainSubDomainBooksAll = &Family{Key: "domain/<sub>/<manifest:domain.books>/*", Kind: "row", Schema: "08-domain/data/book-all.schema.json", Norm: "P/08.5 N1.3 to_all",
	Template: []Seg{{Lit: "domain/", Placeholder: "", Grammar: ""}, {Lit: "", Placeholder: "<sub>", Grammar: "^(?:[a-z][a-z0-9_-]{0,31})$"}, {Lit: "/", Placeholder: "", Grammar: ""}, {Lit: "", Placeholder: "<manifest:domain.books>", Grammar: "^(?:[a-z0-9][a-z0-9_-]*)$"}, {Lit: "/", Placeholder: "", Grammar: ""}, {Lit: "", Placeholder: "*", Grammar: "^(?:[^/]+(?:/[^/]+)*)$"}},
	Outcomes: []Outcome{{Path: "", Reader: "domain", Priority: 0, Unit: "row"}, {Path: "", Reader: "console", Priority: 0, Unit: "row"}, {Path: "", Reader: "domainagent", Priority: 0, Unit: "row"}, {Path: "", Reader: "<s>worker", Priority: 0, Unit: "row"}},
	Doc:      "{\x0a \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\x0a \"$ref\": \"#/$defs/common.book_row\",\x0a \"description\": \"head of the book to: \\\"*\\\": only \\\"\\\" (P/08.5 N1.3 to_all)\",\x0a \"$defs\": {\x0a  \"common.book_missing\": {\x0a   \"description\": \"who is missing in the book — [{member, why}] class server first, within by member in UTF-8 bytes, one per book (P/08.5 N1.3 missing); the order and «one per member» — a rule of the lesson, not the form\",\x0a   \"type\": \"array\",\x0a   \"items\": {\x0a    \"type\": \"object\",\x0a    \"properties\": {\x0a     \"member\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\",\x0a      \"description\": \"the member because of which something is missing in the book\"\x0a     },\x0a     \"why\": {\x0a      \"description\": \"a closed list of words (P/08.5 N1.3 why); a member has one entry\",\x0a      \"type\": \"string\",\x0a      \"enum\": [\x0a       \"unseen\",\x0a       \"silent\",\x0a       \"never\",\x0a       \"no_copy\",\x0a       \"bad_contribution\",\x0a       \"secret_unopened\"\x0a      ]\x0a     }\x0a    },\x0a    \"additionalProperties\": false,\x0a    \"required\": [\x0a     \"member\",\x0a     \"why\"\x0a    ]\x0a   }\x0a  },\x0a  \"common.book_row\": {\x0a   \"description\": \"a row of the assembled book (P/08.5 N1.3 result): the element \\\"\\\" — the JSON text {missing, missing_count}, the element `<key>` — the JSON text {entries} only with elements where the recipient is in to; at the holder the secrets of value — envelopes of the holder's ring enc:v2 (N1.3 at_rest), at the member — envelopes of the member's ring (P/09.1 N1.4 member_row); the keys of the elements — arbitrary\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"\": {\x0a     \"description\": \"the JSON text {missing, missing_count} — the completeness of the book without keys\",\x0a     \"type\": \"object\",\x0a     \"properties\": {\x0a      \"missing\": {\x0a       \"$ref\": \"#/$defs/common.book_missing\",\x0a       \"description\": \"the first MISSING_SHOWN 500: class server first, within by member (P/08.5 N1.3 result)\",\x0a       \"maxItems\": 500\x0a      },\x0a      \"missing_count\": {\x0a       \"description\": \"all members in missing (P/08.5 N1.3 result)\",\x0a       \"$ref\": \"#/$defs/common.uint53\"\x0a      },\x0a      \"term\": {\x0a       \"description\": \"a book to: \\\"*\\\": the term of the write of the row\",\x0a       \"$ref\": \"#/$defs/common.pos53\"\x0a      },\x0a      \"rev\": {\x0a       \"description\": \"a book to: \\\"*\\\": the version of the row\",\x0a       \"$ref\": \"#/$defs/common.pos53\"\x0a      },\x0a      \"stale\": {\x0a       \"description\": \"a book to: \\\"*\\\" with stale: <member>/<server> — the worker of the book's subsystem is silent, the first MISSING_SHOWN 500 by UTF-8 bytes (P/08.5 N1.3 head)\",\x0a       \"type\": \"array\",\x0a       \"maxItems\": 500,\x0a       \"uniqueItems\": true,\x0a       \"items\": {\x0a        \"type\": \"string\"\x0a       }\x0a      },\x0a      \"stale_count\": {\x0a       \"description\": \"all such servers (P/08.5 N1.3 head)\",\x0a       \"$ref\": \"#/$defs/common.uint53\"\x0a      }\x0a     },\x0a     \"additionalProperties\": false,\x0a     \"required\": [\x0a      \"missing\",\x0a      \"missing_count\"\x0a     ],\x0a     \"x-encoding\": \"json\",\x0a     \"x-codec\": [\x0a      \"object\"\x0a     ]\x0a    }\x0a   },\x0a   \"propertyNames\": {\x0a    \"anyOf\": [\x0a     {\x0a      \"enum\": [\x0a       \"\"\x0a      ]\x0a     },\x0a     {\x0a      \"description\": \"key of the book — the value of the field key of the entry, a non-empty string (P/03.7 N1.2 entry)\",\x0a      \"type\": \"string\",\x0a      \"pattern\": \"^(?:[\\\\s\\\\S]+)$\"\x0a     }\x0a    ]\x0a   },\x0a   \"additionalProperties\": {\x0a    \"description\": \"the JSON text {entries}\",\x0a    \"type\": \"object\",\x0a    \"properties\": {\x0a     \"entries\": {\x0a      \"description\": \"the elements of the key for this recipient by (member, item) in UTF-8 bytes (N1.3 order — a rule of the lesson, not the form)\",\x0a      \"type\": \"array\",\x0a      \"items\": {\x0a       \"type\": \"object\",\x0a       \"properties\": {\x0a        \"member\": {\x0a         \"$ref\": \"#/$defs/common.domain_member\",\x0a         \"description\": \"the contributor member — from the origin of the report, not from the input\"\x0a        },\x0a        \"item\": {\x0a         \"description\": \"`<slot>/<item>` for a family, `<item>` for a single row\",\x0a         \"type\": \"string\",\x0a         \"pattern\": \"^(?:[\\\\s\\\\S]+)$\"\x0a        },\x0a        \"value\": {\x0a         \"description\": \"the input object as is; the secrets *_secret — ring envelopes (enc:v2), AAD — the row key 0x00 «/<row item>» + the JSON Pointer of the secret (N1.3 at_rest)\",\x0a         \"type\": \"object\",\x0a         \"x-opaque\": true\x0a        }\x0a       },\x0a       \"additionalProperties\": false,\x0a       \"required\": [\x0a        \"member\",\x0a        \"item\",\x0a        \"value\"\x0a       ]\x0a      }\x0a     }\x0a    },\x0a    \"additionalProperties\": false,\x0a    \"required\": [\x0a     \"entries\"\x0a    ],\x0a    \"x-encoding\": \"json\",\x0a    \"x-codec\": [\x0a     \"object\"\x0a    ]\x0a   },\x0a   \"required\": [\x0a    \"\"\x0a   ]\x0a  },\x0a  \"common.domain_backup_doc\": {\x0a   \"description\": \"the backup document (P/08.8 N1.5 document) — JCS {term, rev, holder, at, members, state, objects, raw?, backup_key_rev, holder_member_key?, issuer, kid, sig}, a closed set; one document at the holder (the object `domain/backups/rev-<rev>`) and at the keeper (the object domain/backup); the signature — by the issuer, the check — the function record of the term record contract (the kind «backup document»; the types — step 1, not_a_record). The document carries no domain: the issuer binds it to the domain (record steps 3–5)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"term\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the holder's term\"\x0a    },\x0a    \"rev\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the backup revision; grows only when the content changes (N1.5 rev)\"\x0a    },\x0a    \"holder\": {\x0a     \"$ref\": \"#/$defs/common.domain_member\",\x0a     \"description\": \"the name of the holder member (P/08.1 N1.1 member)\"\x0a    },\x0a    \"at\": {\x0a     \"description\": \"wall-clock seconds of the signature; a JSON number (record step 1: at — a number)\",\x0a     \"type\": \"number\"\x0a    },\x0a    \"members\": {\x0a     \"description\": \"the names of the member list, without repeats\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\",\x0a      \"description\": \"the member's name\"\x0a     },\x0a     \"uniqueItems\": true\x0a    },\x0a    \"parts\": {\x0a     \"description\": \"part → {sha256, rev, key_rev} (P/08.8 N1.5a)\",\x0a     \"type\": \"object\",\x0a     \"additionalProperties\": true\x0a    },\x0a    \"counts\": {\x0a     \"description\": \"domain/member-count\",\x0a     \"type\": \"object\",\x0a     \"additionalProperties\": true\x0a    },\x0a    \"state\": {\x0a     \"description\": \"{<row key>: {<element>: <text>}} — the rows that the domain decided and that nobody else has (N1.5 state)\",\x0a     \"type\": \"object\",\x0a     \"properties\": {},\x0a     \"propertyNames\": {\x0a      \"description\": \"the key of a state row (N1.5 state)\",\x0a      \"type\": \"string\"\x0a     },\x0a     \"additionalProperties\": {\x0a      \"description\": \"{<element>: <text>}\",\x0a      \"type\": \"object\",\x0a      \"properties\": {},\x0a      \"propertyNames\": {\x0a       \"description\": \"the element of the row\",\x0a       \"type\": \"string\"\x0a      },\x0a      \"additionalProperties\": {\x0a       \"description\": \"the value of the element as stored (text); *_secret — an enc:v2 envelope of the backup key (N1.5 secrets)\",\x0a       \"type\": \"string\"\x0a      }\x0a     }\x0a    },\x0a    \"objects\": {\x0a     \"description\": \"`{<object key>: <JSON>}` — the shared document and the alarm history (N1.5 objects); only objects in the form of their family, as a value\",\x0a     \"type\": \"object\",\x0a     \"x-opaque\": true\x0a    },\x0a    \"raw\": {\x0a     \"description\": \"`{<object key>: <base64>}` — the objects of the copy not in the form of their family — not JSON or JSON not by the form, as bytes (N1.5 raw; C08-BACKUP-JSON-99, the Architect's decision of 2026-10-26)\",\x0a     \"type\": \"object\",\x0a     \"properties\": {},\x0a     \"propertyNames\": {\x0a      \"description\": \"the object key; a key — in objects or in raw, not in both (N1.5 raw; in both — record step 1, not_a_record)\",\x0a      \"type\": \"string\"\x0a     },\x0a     \"additionalProperties\": {\x0a      \"description\": \"base64 of the object's bytes, RFC 4648 §4, with padding; an object of 0 bytes — an empty string\",\x0a      \"type\": \"string\",\x0a      \"pattern\": \"^(?:([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?)$\"\x0a     }\x0a    },\x0a    \"backup_key_rev\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the revision of the backup key (N1.5 backup_key)\"\x0a    },\x0a    \"holder_member_key\": {\x0a     \"description\": \"hex of the public key of the holder member, 32 bytes; the key of the former one in the list after a move (N1.2 former)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:[0-9a-f]{64})$\"\x0a    },\x0a    \"issuer\": {\x0a     \"description\": \"hex of the issuer's public key, 32 bytes (the term record contract)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:[0-9a-f]{64})$\"\x0a    },\x0a    \"kid\": {\x0a     \"description\": \"serial of the issuer — the first 16 characters of hex issuer; anything else — function record steps 3–5, not the form\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"sig\": {\x0a     \"description\": \"base64url without = of the issuer's Ed25519 signature over UTF-8(JCS(doc without kid and sig)), 64 bytes; not base64url, not 64 bytes or does not match — function record step 5 (bad_signature), not the form\",\x0a     \"type\": \"string\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"term\",\x0a    \"rev\",\x0a    \"holder\",\x0a    \"at\",\x0a    \"members\",\x0a    \"state\",\x0a    \"objects\",\x0a    \"backup_key_rev\",\x0a    \"issuer\",\x0a    \"kid\",\x0a    \"sig\"\x0a   ]\x0a  },\x0a  \"common.domain_backup_pointer\": {\x0a   \"description\": \"the pair of the backup and its sum {term, rev, sha256} (P/08.8 N1.5 keepers): the holder's pointer domain/keepers/<member> and the keeper's row domain/backup-taken\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"term\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the term of the holder that issued the backup\"\x0a    },\x0a    \"rev\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the backup revision\"\x0a    },\x0a    \"sha256\": {\x0a     \"$ref\": \"#/$defs/common.sha256_hex\",\x0a     \"description\": \"hex sha256 of the JCS text of the backup document\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"term\",\x0a    \"rev\",\x0a    \"sha256\"\x0a   ]\x0a  },\x0a  \"common.domain_member\": {\x0a   \"description\": \"the member's name — CLUSTER of its installation, 1–64 characters [a-z0-9-] (P/08.1 N1.1 member)\",\x0a   \"type\": \"string\",\x0a   \"pattern\": \"^(?:[a-z0-9-]{1,64})$\"\x0a  },\x0a  \"common.domain_member_entry\": {\x0a   \"description\": \"the member entry Entry (P/08.3 N1.1); by — only at admitted, Entry not larger than ENTRY_MAX 1240 bytes of JCS (P/08.10 N1.5) — checks of the lesson at the writer, not of the form\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"how\": {\x0a     \"description\": \"where the member in the list comes from — \\\"admitted\\\" | \\\"holder\\\" | `\\\"held the domain until term <N>\\\"` (P/08.3 N1.1; the last two — P/08.8 N1.2)\",\x0a     \"type\": \"string\",\x0a     \"not\": {\x0a      \"enum\": [\x0a       \"\"\x0a      ]\x0a     }\x0a    },\x0a    \"since\": {\x0a     \"$ref\": \"#/$defs/common.time\",\x0a     \"description\": \"the holder's wall-clock seconds of the record\"\x0a    },\x0a    \"by\": {\x0a     \"description\": \"the person who admitted the member (P/08.4; before it — operator); only at admitted\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"key\": {\x0a     \"$ref\": \"#/$defs/common.domain_member_key\",\x0a     \"description\": \"the key of the member admitted by the fingerprint; at holder — the key from the first report of its agent\"\x0a    },\x0a    \"revoked_keys\": {\x0a     \"description\": \"the former keys of this name, revoked; not more than the 4 latest (P/08.10 N1.5)\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.domain_member_key\"\x0a     }\x0a    },\x0a    \"ca\": {\x0a     \"description\": \"the member's CA fingerprints (sha256 DER), 1–2, ascending, without repeats (P/08.3 N1.6 Entry.ca)\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.sha256_hex\"\x0a     },\x0a     \"minItems\": 1,\x0a     \"uniqueItems\": true,\x0a     \"maxItems\": 2\x0a    },\x0a    \"class\": {\x0a     \"description\": \"server — a cluster with servers, camera — a camera cluster (P/08.3 N1.1)\",\x0a     \"type\": \"string\",\x0a     \"enum\": [\x0a      \"server\",\x0a      \"camera\"\x0a     ]\x0a    },\x0a    \"url\": {\x0a     \"description\": \"the entry address, not longer than 256 bytes (P/08.1 N1.4)\",\x0a     \"type\": \"string\",\x0a     \"maxLength\": 256\x0a    },\x0a    \"via\": {\x0a     \"description\": \"the member's relay (P/08.3 N1.2)\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"batch\": {\x0a     \"description\": \"the admission batch (P/08.3 N1.1a)\",\x0a     \"type\": \"string\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"how\",\x0a    \"since\"\x0a   ]\x0a  },\x0a  \"common.domain_member_key\": {\x0a   \"description\": \"hex of the member's Ed25519 public key, 32 bytes (the member key P/09.1 N1.1 pub; Entry.key P/08.3 N1.1)\",\x0a   \"type\": \"string\",\x0a   \"pattern\": \"^(?:[0-9a-f]{64})$\"\x0a  },\x0a  \"common.domain_members_doc\": {\x0a   \"description\": \"doc of the holder's row domain/member-rows/<part> (P/08.3 N1.1) and of its copy domain/member-list/<part> at the member — JCS text (P/09.1 N1.1, N1.4)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"domain\": {\x0a     \"description\": \"the domain name (P/08.2 N1.1)\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"part\": {\x0a     \"description\": \"part: 4 digits, 0000…4095 (P/08.3 N1.1)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:0[0-9]{3}|[1-3][0-9]{3}|40[0-8][0-9]|409[0-5])$\"\x0a    },\x0a    \"rev\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"+1 on every write\"\x0a    },\x0a    \"term\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the term of the holder that wrote the row (P/08.8 N1.1; installation — 1)\"\x0a    },\x0a    \"members\": {\x0a     \"description\": \"the entries of the members of this part, the holder is in the count of its own part (P/08.10 N1.5)\",\x0a     \"type\": \"object\",\x0a     \"propertyNames\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\"\x0a     },\x0a     \"additionalProperties\": {\x0a      \"$ref\": \"#/$defs/common.domain_member_entry\"\x0a     }\x0a    },\x0a    \"issuer\": {\x0a     \"description\": \"hex of the issuer's public key\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"kid\": {\x0a     \"description\": \"the first 16 characters of hex issuer\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"sig\": {\x0a     \"description\": \"the issuer's signature over UTF-8(JCS(doc without kid and sig))\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"gathered\": {\x0a     \"description\": \"a row of the gathering «from nothing»: the source of the part at the write, null — there is no source (P/08.8 N1.8a gathered)\",\x0a     \"anyOf\": [\x0a      {\x0a       \"type\": \"object\",\x0a       \"properties\": {\x0a        \"term\": {\x0a         \"$ref\": \"#/$defs/common.pos53\"\x0a        },\x0a        \"rev\": {\x0a         \"$ref\": \"#/$defs/common.pos53\"\x0a        }\x0a       },\x0a       \"additionalProperties\": false,\x0a       \"required\": [\x0a        \"term\",\x0a        \"rev\"\x0a       ]\x0a      },\x0a      {\x0a       \"type\": \"null\"\x0a      }\x0a     ]\x0a    },\x0a    \"new\": {\x0a     \"description\": \"the names new of the part, the members of this row (P/08.8 N1.8a gathered)\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"type\": \"string\",\x0a      \"pattern\": \"^(?:[a-z0-9-]{1,64})$\"\x0a     }\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"domain\",\x0a    \"part\",\x0a    \"rev\",\x0a    \"term\",\x0a    \"members\",\x0a    \"issuer\",\x0a    \"kid\",\x0a    \"sig\"\x0a   ],\x0a   \"x-encoding\": \"jcs\"\x0a  },\x0a  \"common.domain_outcome\": {\x0a   \"description\": \"the outcome of the edit — the JSON text of the element `<id>` of the outcomes row: at the holder domain/outcomes/<member> (P/08.6 N1.6), at the member domain/outcomes (P/09.1 N1.5 outcome)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"id\": {\x0a     \"description\": \"id of the edit (P/08.6 N1.4 id); equal to the element's name — a rule of the lesson (settle, P/08.6 N1.6)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:e-[0-9a-f]{12})$\"\x0a    },\x0a    \"status\": {\x0a     \"description\": \"the response code of the member's console\",\x0a     \"type\": \"integer\",\x0a     \"x-integer\": true\x0a    },\x0a    \"result\": {\x0a     \"description\": \"performed (2xx) | conflict (412) | refused (another 4xx, except «in flight»)\",\x0a     \"type\": \"string\",\x0a     \"enum\": [\x0a      \"performed\",\x0a      \"conflict\",\x0a      \"refused\"\x0a     ]\x0a    },\x0a    \"error\": {\x0a     \"description\": \"detail of the response (no detail — its error) at status ≥ 400, without the values of secrets\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"at\": {\x0a     \"$ref\": \"#/$defs/common.time\",\x0a     \"description\": \"the agent's wall-clock seconds\"\x0a    },\x0a    \"what\": {\x0a     \"description\": \"what of the edit (P/08.6 N1.4)\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"kept_at\": {\x0a     \"$ref\": \"#/$defs/common.time\",\x0a     \"description\": \"at of the edit (P/08.6 N1.4 at)\"\x0a    },\x0a    \"made\": {\x0a     \"description\": \"id of the created unit: POST of the unit, the link with new or create (P/09.1 N1.5 made)\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"by\": {\x0a     \"description\": \"the person of the edit: by of the edit; none — the viewer of the domain (P/08.6 N1.6)\",\x0a     \"type\": \"string\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"id\",\x0a    \"status\",\x0a    \"result\",\x0a    \"at\",\x0a    \"what\",\x0a    \"kept_at\"\x0a   ],\x0a   \"x-encoding\": \"json\"\x0a  },\x0a  \"common.domain_placement\": {\x0a   \"description\": \"the placement record — the holder's row `domain/placement/<sub>/<ref>` (P/08.6 N1.1) and its copy at the member `domain/placed/<sub>/<ref>` («the elements of the record as at the holder», P/09.1 N1.5 member)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"cluster\": {\x0a     \"$ref\": \"#/$defs/common.domain_member\",\x0a     \"description\": \"the executor member; required; \\\"\\\" — not by the form (the form of the door — 400, P/08.6 N1.1 form)\"\x0a    },\x0a    \"origin\": {\x0a     \"description\": \"the member owning the source; \\\"\\\" — none; origin — not an executor (P/08.6 N1.1 executors)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:([a-z0-9-]{1,64})?)$\"\x0a    },\x0a    \"copies\": {\x0a     \"description\": \"the JCS text of an array of other executors, ascending, without repeats, without cluster; \\\"[]\\\" — none (the order and «without cluster» — rules of the lesson, not of the form)\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\",\x0a      \"description\": \"another executor\"\x0a     },\x0a     \"uniqueItems\": true,\x0a     \"x-encoding\": \"jcs\"\x0a    },\x0a    \"reason\": {\x0a     \"description\": \"the operator's words; \\\"\\\" — none\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"at\": {\x0a     \"$ref\": \"#/$defs/common.time\",\x0a     \"description\": \"wall-clock seconds of the domain process of the write\"\x0a    },\x0a    \"rev\": {\x0a     \"description\": \"the value of the counter domain/placement of this record, as decimal text (P/08.6 N1.1 rev)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:[1-9][0-9]*)$\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"cluster\",\x0a    \"origin\",\x0a    \"copies\",\x0a    \"reason\",\x0a    \"at\",\x0a    \"rev\"\x0a   ]\x0a  },\x0a  \"common.domain_topology_doc\": {\x0a   \"description\": \"doc of the holder's row domain/topology (P/08.3 N1.2) and of its copy domain/member-topology at the member — JCS text (P/09.1 N1.4)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"rev\": {\x0a     \"$ref\": \"#/$defs/common.uint53\",\x0a     \"description\": \"0 — «never written»; +1 per write\"\x0a    },\x0a    \"centre\": {\x0a     \"$ref\": \"#/$defs/common.domain_member\",\x0a     \"description\": \"a member — the centre of the domain; none — there is no centre\"\x0a    },\x0a    \"star\": {\x0a     \"description\": \"star relays, ascending, without repeats\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\"\x0a     },\x0a     \"uniqueItems\": true\x0a    },\x0a    \"via\": {\x0a     \"description\": \"member → the relay through which it reports; no member — directly\",\x0a     \"type\": \"object\",\x0a     \"propertyNames\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\"\x0a     },\x0a     \"additionalProperties\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\"\x0a     }\x0a    },\x0a    \"by\": {\x0a     \"description\": \"who wrote — the name proven by the gate\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"at\": {\x0a     \"$ref\": \"#/$defs/common.time\",\x0a     \"description\": \"when written (the console's wall-clock seconds)\"\x0a    },\x0a    \"relays\": {\x0a     \"description\": \"who leads at least one member (P/08.3 N1.2)\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.domain_member\"\x0a     },\x0a     \"uniqueItems\": true\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"rev\",\x0a    \"star\"\x0a   ],\x0a   \"x-encoding\": \"jcs\"\x0a  },\x0a  \"common.grants_doc\": {\x0a   \"description\": \"the JCS text {lines} of the grants row (P/08.4 N1.3); the member's copy carries it as it came (P/09.1 N1.4 member_copy)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"lines\": {\x0a     \"description\": \"lines by (subject, cap, sub, scope) in UTF-8 bytes, then until by number, without repeats by (subject, cap, sub, scope, until) — the order and the repeat — a rule of the row (P/08.4 N1.3 lines), not the form\",\x0a     \"type\": \"array\",\x0a     \"items\": {\x0a      \"$ref\": \"#/$defs/common.grants_line\"\x0a     }\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"lines\"\x0a   ],\x0a   \"x-encoding\": \"jcs\"\x0a  },\x0a  \"common.grants_line\": {\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"subject\": {\x0a     \"description\": \"a person's name (N1.1), a subject of the name index (chapter 8.5 N1.7) or role:<role name> (N1.3a, up to 69 characters); the form of the name — N1.1 (N3 «grants» step 3)\",\x0a     \"anyOf\": [\x0a      {\x0a       \"$ref\": \"#/$defs/common.person_name\"\x0a      },\x0a      {\x0a       \"type\": \"string\",\x0a       \"pattern\": \"^(?:role:[^\\u0000- \x7f   -     　:|()\\\"/]{1,64})$\"\x0a      }\x0a     ]\x0a    },\x0a    \"cap\": {\x0a     \"description\": \"none < view < edit < admin; none — only at a role row (ADR-0099 §1): a rule of the row, not the form\",\x0a     \"type\": \"string\",\x0a     \"enum\": [\x0a      \"none\",\x0a      \"view\",\x0a      \"edit\",\x0a      \"admin\"\x0a     ]\x0a    },\x0a    \"sub\": {\x0a     \"description\": \"the manifest name (P/02.1 N1.2 name) or platform; no field — the row is in force in all subsystems and in platform (ADR-0097 §1)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:[a-z][a-z0-9_-]{0,31})$\"\x0a    },\x0a    \"scope\": {\x0a     \"description\": \"`*` | `unit:<sub>/<id>` | `labels:<label>[,<label>…]` \\\\| `folder:<id>` (P/08.4 N1.3 scope): `<sub>` — the manifest name (P/02.1), `<id>` — by the identifier grammar P/06.1 N1.3 (named_id: not . and ..), labels — the label alphabet common/contracts/labels.md; labels without repeats — a rule of the row, not the form; `folder:<id>` — the folder id, 32 lowercase hex digits (P/06.8 N1.1)\",\x0a     \"type\": \"string\",\x0a     \"not\": {\x0a      \"type\": \"string\",\x0a      \"pattern\": \"^(?:unit:[a-z][a-z0-9_-]{0,31}/\\\\.\\\\.?)$\"\x0a     },\x0a     \"pattern\": \"^(?:\\\\*|unit:[a-z][a-z0-9_-]{0,31}/[^/\\\\\\\\|\\\",\\u0000-\\u001f\x7f-  ٠-٩۰-۹߀-߉०-९০-৯੦-੯૦-૯୦-୯௦-௯౦-౯೦-೯൦-൯෦-෯๐-๙໐-໙༠-༩၀-၉႐-႙០-៩᠐-᠙᥆-᥏᧐-᧙᪀-᪉᪐-᪙᭐-᭙᮰-᮹᱀-᱉᱐-᱙꘠-꘩꣐-꣙꤀-꤉꧐-꧙꧰-꧹꩐-꩙꯰-꯹０-９𐒠-𐒩𐴰-𐴹𑁦-𑁯𑃰-𑃹𑄶-𑄿𑇐-𑇙𑋰-𑋹𑑐-𑑙𑓐-𑓙𑙐-𑙙𑛀-𑛉𑜰-𑜹𑣠-𑣩𑥐-𑥙𑱐-𑱙𑵐-𑵙𑶠-𑶩𑽐-𑽙𖩠-𖩩𖫀-𖫉𖭐-𖭙𝟎-𝟿𞅀-𞅉𞋰-𞋹𞓰-𞓹𞥐-𞥙🯰-🯹]+|labels:[A-Za-z0-9][A-Za-z0-9_.:-]{0,63}(,[A-Za-z0-9][A-Za-z0-9_.:-]{0,63})*|folder:[0-9a-f]{32})$\"\x0a    },\x0a    \"until\": {\x0a     \"$ref\": \"#/$defs/common.time\",\x0a     \"description\": \"0 — without a deadline; otherwise wall-clock seconds — the line is in force while now < until; an input with more than three fraction digits — rounding to thousandths (P/08.4 N1.3 until); compared by value (0 and 0.0 — one line)\"\x0a    },\x0a    \"by\": {\x0a     \"description\": \"the name proven by the gate at the write; a line matching by (subject, cap, scope, until) keeps its by\",\x0a     \"type\": \"string\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"subject\",\x0a    \"cap\",\x0a    \"scope\",\x0a    \"until\",\x0a    \"by\"\x0a   ]\x0a  },\x0a  \"common.named_id\": {\x0a   \"description\": \"unit id by a field (P/06.1 N1.3 named): non-empty; without / \\\\ | \\\" comma, control characters (Cc), line and paragraph separators (Zl, Zp) and digits outside 0–9 (non-ASCII Nd); the categories — Unicode 15.0.0\",\x0a   \"type\": \"string\",\x0a   \"not\": {\x0a    \"enum\": [\x0a     \".\",\x0a     \"..\"\x0a    ]\x0a   },\x0a   \"pattern\": \"^(?:[^/\\\\\\\\|\\\",\\u0000-\\u001f\x7f-  ٠-٩۰-۹߀-߉०-९০-৯੦-੯૦-૯୦-୯௦-௯౦-౯೦-೯൦-൯෦-෯๐-๙໐-໙༠-༩၀-၉႐-႙០-៩᠐-᠙᥆-᥏᧐-᧙᪀-᪉᪐-᪙᭐-᭙᮰-᮹᱀-᱉᱐-᱙꘠-꘩꣐-꣙꤀-꤉꧐-꧙꧰-꧹꩐-꩙꯰-꯹０-９𐒠-𐒩𐴰-𐴹𑁦-𑁯𑃰-𑃹𑄶-𑄿𑇐-𑇙𑋰-𑋹𑑐-𑑙𑓐-𑓙𑙐-𑙙𑛀-𑛉𑜰-𑜹𑣠-𑣩𑥐-𑥙𑱐-𑱙𑵐-𑵙𑶠-𑶩𑽐-𑽙𖩠-𖩩𖫀-𖫉𖭐-𖭙𝟎-𝟿𞅀-𞅉𞋰-𞋹𞓰-𞓹𞥐-𞥙🯰-🯹]+)$\"\x0a  },\x0a  \"common.person_name\": {\x0a   \"description\": \"the person's name (P/08.4 N1.1 name): 1–64 characters without whitespace, control characters (U+0000–U+001F, U+007F) and : | ( ) \\\" /; not exactly break-glass; whitespace — the White_Space property of Unicode 15.0.0, written out as characters (the Architect's decision of 2026-10-20 on the questions of assembling lesson 8, item 3); «not a subject of the name index» — a check of the door (chapter 8.5 N1.7), not the form\",\x0a   \"type\": \"string\",\x0a   \"not\": {\x0a    \"enum\": [\x0a     \"break-glass\"\x0a    ]\x0a   },\x0a   \"pattern\": \"^(?:[^\\u0000- \x7f   -     　:|()\\\"/]{1,64})$\"\x0a  },\x0a  \"common.pos53\": {\x0a   \"description\": \"an integer from 1 to 2^53 − 1\",\x0a   \"type\": \"integer\",\x0a   \"x-integer\": true,\x0a   \"minimum\": 1,\x0a   \"maximum\": 9007199254740991\x0a  },\x0a  \"common.sha256_hex\": {\x0a   \"description\": \"sha256 — 64 lowercase hex digits (P/02.3 N1.5)\",\x0a   \"type\": \"string\",\x0a   \"pattern\": \"^(?:[0-9a-f]{64})$\"\x0a  },\x0a  \"common.shared_doc\": {\x0a   \"description\": \"the shared document of the domain (P/08.9 N1.2 document) — JCS {domain, term, rev, at, by, shared, issuer, kid, sig}, a closed set; one document at the holder (the object `domain/shared-docs/rev-<rev>`) and at the member (the object domain/shared — a copy taken by the agent, P/09.1 N1.10); the signature — by the issuer, the check — the function record of the term record contract (the kind «shared document»)\",\x0a   \"type\": \"object\",\x0a   \"properties\": {\x0a    \"domain\": {\x0a     \"description\": \"the domain name (chapter 8.2, from М11/2 N1.1); another JSON type or ≠ the domain of the set — function record step 2 (another_domain), not the form (REC-G01)\"\x0a    },\x0a    \"term\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the holder's term (chapter 8.8, from М11/10 N1.1); the order — (term, rev), term is senior\"\x0a    },\x0a    \"rev\": {\x0a     \"$ref\": \"#/$defs/common.pos53\",\x0a     \"description\": \"the edit number\"\x0a    },\x0a    \"at\": {\x0a     \"description\": \"wall-clock seconds of the signature\",\x0a     \"type\": \"number\"\x0a    },\x0a    \"by\": {\x0a     \"description\": \"the name proven by the gate; after a move — \\\"domain\\\"\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"shared\": {\x0a     \"description\": \"`{<sub>: {<name>: <value>}}` — only what is declared P/02.1 N1.2b; subsystems and names ascending (JCS)\",\x0a     \"type\": \"object\",\x0a     \"propertyNames\": {\x0a      \"$ref\": \"#/$defs/common.sub_name\"\x0a     },\x0a     \"additionalProperties\": {\x0a      \"description\": \"the values of the subsystem `<sub>` — the names of its domain.shared\",\x0a      \"type\": \"object\",\x0a      \"propertyNames\": {\x0a       \"type\": \"string\"\x0a      },\x0a      \"additionalProperties\": {\x0a       \"description\": \"the value of a field or a document declared by domain.shared of the manifest\"\x0a      }\x0a     }\x0a    },\x0a    \"issuer\": {\x0a     \"description\": \"hex of the issuer's public key (the term record contract, issuing_key_secret)\",\x0a     \"type\": \"string\",\x0a     \"pattern\": \"^(?:[0-9a-f]{64})$\"\x0a    },\x0a    \"kid\": {\x0a     \"description\": \"serial of the issuer — the first 16 characters of hex issuer; anything else — function record steps 3–5, not the form (REC-G01)\",\x0a     \"type\": \"string\"\x0a    },\x0a    \"sig\": {\x0a     \"description\": \"base64url without «=» of the issuer's Ed25519 signature over UTF-8(JCS(doc without kid and sig)), 64 bytes; anything else — function record step 5 (bad_signature), not the form (REC-G01)\",\x0a     \"type\": \"string\"\x0a    }\x0a   },\x0a   \"additionalProperties\": false,\x0a   \"required\": [\x0a    \"domain\",\x0a    \"term\",\x0a    \"rev\",\x0a    \"at\",\x0a    \"by\",\x0a    \"shared\",\x0a    \"issuer\",\x0a    \"kid\",\x0a    \"sig\"\x0a   ]\x0a  },\x0a  \"common.sub_name\": {\x0a   \"description\": \"the subsystem name (P/02.1 N1.2)\",\x0a   \"type\": \"string\",\x0a   \"pattern\": \"^(?:[a-z][a-z0-9_-]{0,31})$\"\x0a  },\x0a  \"common.time\": {\x0a   \"description\": \"time N0 P/01.1 «Time in a row»\",\x0a   \"type\": [\x0a    \"string\",\x0a    \"number\"\x0a   ],\x0a   \"x-time\": true\x0a  },\x0a  \"common.uint53\": {\x0a   \"description\": \"an integer from 0 to 2^53 − 1\",\x0a   \"type\": \"integer\",\x0a   \"x-integer\": true,\x0a   \"minimum\": 0,\x0a   \"maximum\": 9007199254740991\x0a  }\x0a }\x0a}\x0a"}

